import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    trades = inputs["trades"].copy()

    # Sort by account_id, symbol, then trade_ts, then trade_id (for deterministic processing)
    trades = trades.sort_values(
        by=['account_id', 'symbol', 'trade_ts', 'trade_id'],
        ignore_index=True
    )

    # Track open lots and sell results
    open_lots_list = []  # list of dicts: {lot_trade_id, account_id, symbol, remaining_qty, price}
    sell_results_list = []  # list of dicts: {trade_id, matched_qty, short_qty, realized_pnl}

    # Process trades sequentially per (account_id, symbol)
    for (acct_id, symbol), group in trades.groupby(['account_id', 'symbol'], sort=False):
        # Within each account/symbol group, process in order
        group = group.sort_values(by=['trade_ts', 'trade_id'], ignore_index=True)

        # Lots open for this (account_id, symbol)
        lots = []  # list of dicts: {lot_trade_id, remaining_qty, price, open_index}

        for _, trade in group.iterrows():
            trade_id = int(trade['trade_id'])
            side = trade['side']
            qty = int(trade['qty'])
            price = float(trade['price'])

            if side == 'BUY':
                # Open a new lot
                lots.append({
                    'lot_trade_id': trade_id,
                    'remaining_qty': qty,
                    'price': price,
                    'open_index': len(lots)  # Track order of opening
                })
            elif side == 'SELL':
                # Match SELL against lots in FIFO order (oldest first)
                still_to_sell = qty
                matched_qty = 0
                realized_pnl = 0.0

                # Sort lots by open_index to maintain FIFO order
                lots.sort(key=lambda x: x['open_index'])

                # Consume lots from oldest to newest
                for lot in lots:
                    if still_to_sell == 0:
                        break

                    if lot['remaining_qty'] > 0:
                        take = min(lot['remaining_qty'], still_to_sell)
                        realized_pnl += take * (price - lot['price'])
                        lot['remaining_qty'] -= take
                        matched_qty += take
                        still_to_sell -= take

                short_qty = max(0, qty - matched_qty)

                sell_results_list.append({
                    'trade_id': trade_id,
                    'matched_qty': matched_qty,
                    'short_qty': short_qty,
                    'realized_pnl': realized_pnl
                })

        # Add remaining open lots (with remaining_qty > 0) to output
        for lot in lots:
            if lot['remaining_qty'] > 0:
                open_lots_list.append({
                    'lot_trade_id': lot['lot_trade_id'],
                    'account_id': acct_id,
                    'symbol': symbol,
                    'remaining_qty': lot['remaining_qty'],
                    'price': lot['price']
                })

    # Build output DataFrames
    if sell_results_list:
        sell_results_df = pd.DataFrame(sell_results_list)
        sell_results_df = sell_results_df[['trade_id', 'matched_qty', 'short_qty', 'realized_pnl']]
    else:
        sell_results_df = pd.DataFrame(
            columns=['trade_id', 'matched_qty', 'short_qty', 'realized_pnl']
        )
        sell_results_df = sell_results_df.astype({
            'trade_id': 'int64',
            'matched_qty': 'int64',
            'short_qty': 'int64',
            'realized_pnl': 'float64'
        })

    if open_lots_list:
        open_lots_df = pd.DataFrame(open_lots_list)
        open_lots_df = open_lots_df[['lot_trade_id', 'account_id', 'symbol', 'remaining_qty', 'price']]
    else:
        open_lots_df = pd.DataFrame(
            columns=['lot_trade_id', 'account_id', 'symbol', 'remaining_qty', 'price']
        )
        open_lots_df = open_lots_df.astype({
            'lot_trade_id': 'int64',
            'account_id': 'int64',
            'symbol': 'str',
            'remaining_qty': 'int64',
            'price': 'float64'
        })

    return {
        'sell_results': sell_results_df,
        'open_lots': open_lots_df
    }
